interface Greeter {
    fn greet(self) -> String
    fn greetLoud(self) -> String {
        self.greet()
    }
}
record User { name: String }
impl Greeter for User {
    fn greet(self) -> String {
        "hi"
    }
}
pub type AppError = Failed(String)
pub fn main() -> Result<(), AppError> {
    let u = User { name: "a" }
    let text = u.greetLoud()
    return Ok(())
}

